query:
-- Add new payout status values
ALTER TYPE payout_status ADD VALUE IF NOT EXISTS 'pending_approval';
ALTER TYPE payout_status ADD VALUE IF NOT EXISTS 'rejected';

-- Add settlement frequency enum
DO $$ BEGIN
  CREATE TYPE settlement_freq AS ENUM ('daily', 'weekly', 'monthly');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- Add approval and settlement columns to merchants
ALTER TABLE merchants
  ADD COLUMN IF NOT EXISTS payout_approval_threshold BIGINT NOT NULL DEFAULT 500000,
  ADD COLUMN IF NOT EXISTS payout_approval_enabled BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS settlement_frequency settlement_freq NOT NULL DEFAULT 'daily',
  ADD COLUMN IF NOT EXISTS settlement_min_amount BIGINT NOT NULL DEFAULT 10000,
  ADD COLUMN IF NOT EXISTS settlement_bank_code TEXT,
  ADD COLUMN IF NOT EXISTS settlement_account_number TEXT,
  ADD COLUMN IF NOT EXISTS settlement_account_name TEXT;

